"""Assemble measured facts only; prespecified gate controls stage3 scope."""
from common import *
def main():
 c=cfg();gate=json.loads((D/'단계3_판정.json').read_text());summary=json.loads((D/'tables/stage0/summary_size_annotations.json').read_text())['rows'];top=json.loads((D/'tables/stage0/top3_definition_differences.json').read_text())['rows'];sims=json.loads((D/'tables/stage1/simulation_table.json').read_text())['rows'];names=dict(zip(c['stage0']['methods'],['사전 정보','MVS','결합','기준선','GeoGS','2DGS','CDGS','판단 조합','V0']))
 lines=['# PHD-MAIN-RELEASE-v1 보고','', 'scientific_verdict: null. 통합 발주문 v2. 아래 값은 측정 사실이며 과학적 판정이 아니다.','', '단계 0·1·2 완료. 단계 3은 사전 조건 미충족으로 미실행. 고른 규칙 없음.','', '| 가장 큰 어긋남 · 기존 칸 | 비율 % | MVS 면이 기둥 안에 있는 비율 % | 확인된 정의 차이 |','|---|---:|---:|---|']
 for r in top:lines.append(f"| {LABELS[r['site']]} {r['prior']} 칸 {r['cell']} | {r['mismatch_fraction']*100:.3f} | {r['mvs_surface_in_column_pct']:.3f} | {r['confirmed_definition_difference']} |")
 lines+=['','각 정의 차이의 기여율은 분리하지 않았다. 원인별 기여는 확인 불가다. 칸 정의·목표 맞음은 핵심점 법선 방향 스칼라와 패치 넓이, 완전성은 참값 행과 원래 표면의 최근접 거리를 쓴다. 기둥은 원 채점기의 결과점 소속 규칙이며 전역 최근접 탐색을 제한하지 않는다. 새 칸에서는 면 존재만 정확한 삼각형·기둥 교차로 확인했다.','', '채점 기준 칸, τ 1배. 최대 차이는 판단 조합을 뺀 방법의 해당 칸 최고와 비교한다. 작은 칸도 포함하고 해당 최대 차이 위치에 표시했다.','', '| 방법 | B173 주변·B0 최대 차이 %p | 여섯 장면 최대 차이 %p | 여섯 장면 최대 자리·점 수 |','|---|---:|---:|---|']
 for method in c['stage0']['methods']:
  rr=[next(r for r in summary if r['tau_multiplier']==1 and r['cell_basis']=='score' and r['scope']==scope and r['method']==method) for scope in ['B173_B0','all_six']];r=rr[1];lines.append(f"| {names[method]} | {rr[0]['max_gap_pp']:.3f} {rr[0]['max_gap_small']} | {r['max_gap_pp']:.3f} {r['max_gap_small']} | {LABELS[r['max_gap_site']]} {r['max_gap_prior']} 칸 {r['max_gap_cell']}, {r['max_gap_n_gt']}점 |")
 changes=json.loads((D/'tables/stage0/rank_changes.json').read_text())['rows'];lines+=['','| τ 0.5→0.75→1→1.5→2에서 순서·동률 변화 쌍 | B173 주변·B0 | 여섯 장면 |','|---|---:|---:|']
 for basis,label in [('original','기존 칸'),('score','채점 기준 칸')]:lines.append('| '+label+' | '+' | '.join(str(sum(r['cell_basis']==basis and r['scope']==scope for r in changes)) for scope in ['B173_B0','all_six'])+' |')
 lines+=['','최솟값·최대 차이 위치·3/5/10 %p 이내 칸 수는 tables/stage0/summary_size_annotations.csv, 방법쌍별 순서 변화는 rank_changes.csv. 전체 표 4는 CSV로 제공한다. τ 1배 기존 칸은 54개 결과 모두 원 표 4와 차이 0.00000000 %p였다.','', '단계 3 판정은 기존 칸 기준이다. 실패 점에서 풀림이 최다인 조건은 거짓이었다. 아래 모의 가·나 어느 값도 V0보다 10 %p 넘게 증가하지 않았다. 판정은 단계3_판정.json에 저장하고 커밋한 뒤 고침 비교를 열지 않았다.','', '| R1 사전 정보 | 방법 | 기존 칸 2 완전성 % | 기존 칸 4 완전성 % | 장면 완전성 % | 장면 정확성 % |','|---|---|---:|---:|---:|---:|']
 for prior in ['ALS','LoD2']:
  for method,label in [('FINALTRAIN_30000','V0'),('judgment_mesh','판단 조합'),('sim_delete_released','모의 가: 풀림 뺌'),('sim_pull_released','모의 나: 풀림 당김'),('sim_delete_background','모의 다: 배경 뺌')]:
   rr=[r for r in sims if r['prior']==prior and r['method']==method]
   def num(k,field):
    r=next((r for r in rr if r['cell']==k),None);return '확인 불가' if r is None or r[field] is None else f"{100*r[field]:.3f}"
   lines.append(f"| {prior} | {label} | {num(2,'completeness')} | {num(4,'completeness')} | {num(-1,'completeness')} | {num(-1,'accuracy')} |")
 lines+=['','모의는 학습 없이 저장 모델에 한 번 적용한 위쪽 짐작이다. 대상 선택에는 참값을 쓰지 않았다. 칸 0·1·2·4와 장면 전체의 네 값 및 제거·이동 수는 tables/stage1/simulation_table.csv. 고른 규칙이 없어 V0→고른 규칙 비교는 해당 없음이다.','', '기대와 다른 사실: 실패 점의 최다 꼬리표는 풀림이 아니라 배경이었다. 풀림을 당긴 모의는 R1 항공 LiDAR 칸 2·4 완전성이 V0보다 낮았다. 현재 유효한 목표 후보가 있는 풀림은 ALS 6,096개, LoD2 4,632개였다. 현재 위치를 가·나에 강제로 넣지 않고 셋째 항목으로 남겼다.','', '| 기록 학습 · 15,000회 | 사건 수 | 반복 시간 비율 중앙값 / V0 | 상태 |','|---|---:|---:|---|']
 for prior in ['ALS','LoD2']:
  p=O/'events'/f'R1rep_b10__{prior}__rlog_{prior}_s0'/'receipt.json';r=json.loads(p.read_text());rec=json.loads((O/'runs/R1rep_b10'/f'rlog_{prior}_s0/receipt.json').read_text());lines.append(f"| {prior} | {r['events']} | {r['median_iteration_ratio_vs_V0']:.3f} | {rec['status']} |")
 lines+=['','기록은 점검별 배열로 모아 저장했다. 반복 시간 비교에는 동시 실행한 계보 렌더·CPU 작업의 영향이 포함된다. 7,000회 두 판 모두 건강 점검을 통과했다. 기본값·기록 on/off는 작은 예제 100회에서 모델·Adam·결정·카메라 순서가 같았고 복제·분할·정리도 같았다. 장기 실행 결과의 동일성 검사는 아니며, 7,000·15,000회 풀림 수는 V0와 다르다. 그 차이와 평가 범위 안·밖 수를 stage2 표에 그대로 남겼다. 차이의 원인을 분리한 실험은 하지 않았다.','', '기준·확인 불가: 새 칸의 목표 넓이는 동일 패치 안 참값 행 수 비율로 넓이를 분할했다. 참값 행 없는 패치 넓이는 stage0/*/unassigned.json에 따로 남겼다. 판단 정확도는 원 JUDGEAPPLY와 같은 칸 1·2 넓이 분모이며 미판단은 상·하한으로 남겼다. 결과점 새 칸은 기존 기둥 소속을 유지하고 그 소속의 가장 가까운 참값 행에 연결했다.','면 있는 점 계보는 최대 alpha×T와 깊이 0.25 m 대응 시점의 최빈 번호다. 면 없음 점은 참값 투영 화소의 기여자에 전경 가림을 포함한다. 깊이 0 시점은 가림 없음으로 추정하지 않았다. 벽 앞·뒤는 최빈 기여자를 지지한 첫 학습 카메라 기준이며 R1 LoD2 18점은 앞·뒤 확인 불가다. 최초 풀림 상태는 같은 init_id 계보가 저장 상태에 처음 나타난 시점으로, V0의 고유 부모 사건 시각은 확인 불가다.','', '산출물: 단계0_보고.md·단계0_추가표.md, 단계1_보고.md, 단계2_보고.md; 표는 tables/stage0·stage1·stage2; 그림은 figures/stage0 4장, stage1 4장, stage2 2장. 그림마다 출처 JSON이 있다. 기준 대조 코드 경로·줄·키는 criteria_comparison.csv, 실제 지붕·벽 τ는 tau_values.csv. 실행 오류와 보정은 issues.md, 바꾼 줄은 r24_changed_lines.diff, 재실행 경로는 재실행_경로.md.','설정 최초 잠금: '+c['created_at']+' / SHA256 '+sha(C/'release_v1.json')+'. 기존 r23·RESCORE·FINALTRAIN 설정과 결과는 보존했다. 참값은 채점·출처 셈·그림에만 사용했다.']
 assert gate['stage3_authorized'] is False,'Use stage3 report path for positive gate'
 text='\n'.join(lines)+'\n';assert len(text)<=12000;(D/'보고.md').write_text(text);print('REPORT_CHARACTERS',len(text),flush=True)
if __name__=='__main__':main()
